styles:
body { margin: 0; }
    a { color: #6b521f; text-decoration: underline; text-decoration-color: rgba(138,109,59,0.35); }
    a:hover { color: #5c4826; }
    ::selection { background: rgba(138,109,59,0.25); }

logic:
class Component extends DCLogic {
  state = {
    zoomIndex: null,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    dragOffsetStartX: 0,
    dragOffsetStartY: 0
  };

  noteData = [
    {
      key: "1947",
      label: "Dos Pesos Oro \u00b7 7 de agosto de 1947",
      denomination: "Dos Pesos Oro",
      date: "7 de agosto de 1947",
      obverse: "Guilloches rosados y negros en óvalos ornamentales a ambos lados. Óvalo central con el retrato de Camilo Torres Tenorio, identificado con la leyenda \u201cTORRES\u201d. Grandes cifras decorativas \u201c2\u201d en marcos ornamentales. Numeración roja \u201cN.\u00b0 24062382\u201d, Serie I. Firmas de Gerente y Secretario. Texto: \u201cEL BANCO DE LA REP\u00daBLICA \u00b7 BOGOT\u00c1, COLOMBIA \u00b7 PAGAR\u00c1 AL PORTADOR \u00b7 DOS PESOS ORO\u201d.",
      reverse: "Orla oscura muy ornamentada con guilloches en tonos violeta y negro. Medallón central con el perfil de la Mariana de la Libertad. Grandes cifras \u201c2\u201d decorativas. Texto: \u201cBANCO DE LA REP\u00daBLICA \u00b7 BOGOT\u00c1, COLOMBIA \u00b7 DOS PESOS ORO\u201d.",
      printer: "American Bank Note Company, Nueva York",
      condition: "Muy buen grado circulado: manejo ligero, colores intensos y papel de buena calidad.",
      pick: "Pick #385 (tipo, serie 1923\u20131955)",
      description: "Billete circulado impreso por American Bank Note Company, correspondiente a la larga serie de Dos Pesos Oro con el retrato de Camilo Torres, en circulación desde 1923.",
      jpg: "uploads/colombia-banco-de-la-republica-2-pesos-oro-1947.jpg",
      webp: "uploads/colombia-banco-de-la-republica-2-pesos-oro-1947.webp",
      webp640: "uploads/colombia-banco-de-la-republica-2-pesos-oro-1947-640.webp",
      alt: "Billete de Dos Pesos Oro de El Banco de la República, Colombia, fechado 7 de agosto de 1947, anverso con el retrato de Camilo Torres Tenorio y reverso con un medallón de la Mariana de la Libertad"
    },
    {
      key: "1972",
      label: "Dos Pesos Oro (Muestra) \u00b7 1 de enero de 1972",
      denomination: "Dos Pesos Oro (Muestra)",
      date: "1 de enero de 1972",
      obverse: "Multicolor, predominan el violeta, verde y rosa en los guilloches. Óvalo con el retrato de Policarpa Salavarrieta (\u201cLa Pola\u201d) a la izquierda. Gran cifra ornamental \u201c2\u201d y la denominación \u201cDOS PESOS ORO\u201d. Sobreimpresión roja \u201cMUESTRA\u201d en diagonal. Numeración en ceros y firmas tachadas por perforaciones.",
      reverse: "Multicolor con bordes intrincados. Viñeta central con una balsa muisca del Museo del Oro de Bogotá, enmarcada por guilloches. Grandes cifras ornamentales \u201c2\u201d. Sobreimpresión roja \u201cMUESTRA\u201d.",
      printer: "Estilo American Bank Note Company, con elementos de producción local",
      condition: "Gema sin circular / superior. Perforación de cancelación característica, papel fresco, colores vívidos.",
      pick: "Pick #413 (tipo, serie 1972\u20131973)",
      description: "Espécimen \u201cMUESTRA\u201d del diseño renovado de esta denominación, con el retrato de Policarpa Salavarrieta y una balsa muisca del Museo del Oro en el reverso.",
      jpg: "uploads/colombia-banco-de-la-republica-2-pesos-oro-1972-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-2-pesos-oro-1972-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-2-pesos-oro-1972-specimen-640.webp",
      alt: "Billete especimen de Dos Pesos Oro de El Banco de la República, Colombia, fechado 1 de enero de 1972, anverso con el retrato de Policarpa Salavarrieta y reverso con una balsa muisca"
    }
  ];

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };

  openZoomAt = (index) => {
    this.setState({ zoomIndex: index, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };

  closeZoom = () => {
    this.setState({ zoomIndex: null });
  };

  stopPropagation = (e) => e.stopPropagation();

  zoomIn = () => {
    this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  };

  zoomOut = () => {
    this.setState(s => {
      const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({
      dragging: true,
      dragStartX: e.clientX,
      dragStartY: e.clientY,
      dragOffsetStartX: this.state.offsetX,
      dragOffsetStartY: this.state.offsetY
    });
  };

  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };

  onPointerUp = () => this.setState({ dragging: false });

  onKeyDown = (e) => {
    if (e.key === "Escape" && this.state.zoomIndex !== null) this.closeZoom();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    const notes = this.noteData.map((n, i) => Object.assign({}, n, { openZoom: () => this.openZoomAt(i) }));
    const active = s.zoomIndex !== null ? this.noteData[s.zoomIndex] : null;

    return {
      notes,
      zoomIndex: s.zoomIndex !== null,
      closeZoom: this.closeZoom,
      stopPropagation: this.stopPropagation,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",
      activeNoteJpg: active ? active.jpg : "",
      activeNoteWebp: active ? active.webp : ""
    };
  }
}
